#Requires -Version 5.1
# Fixed operator read-only probe; no copy, GPO writer, service or key access.
$ErrorActionPreference='Stop';Set-StrictMode -Version 2
if($env:COMPUTERNAME -ine 'DC01' -or -not [Environment]::Is64BitProcess){throw 'EXPECTED_DC01_X64_REQUIRED'}
$awLibrary=''
$awLibraryHash='26b578a4ecf3177afa21092cd790995abf1b4a6e6ee73aaf5565653a4a824cf9'
$awBytes=[Convert]::FromBase64String($awLibrary);$awSha=[Security.Cryptography.SHA256]::Create()
try{$awActual=([BitConverter]::ToString($awSha.ComputeHash($awBytes))).Replace('-','').ToLowerInvariant()}finally{$awSha.Dispose()}
if($awActual -cne $awLibraryHash){throw 'REVIEWED_LIBRARY_HASH_MISMATCH'}
. ([scriptblock]::Create([Text.UTF8Encoding]::new($false,$true).GetString($awBytes)))
Import-Module GroupPolicy -ErrorAction Stop
$awGpo=[guid]'8c6808fd-a382-4bf2-9c9c-d9e1d46082a3'
$awDomain='vizyonveri.local';$awServer='dc01.vizyonveri.local'
$awMarker='AuthWireDeployment:v1;instance=4c23eebe-0715-46d1-88ee-a2e96ad7ee46;host=0fa4143f-aae3-4bc3-9cd3-db8a1de24acd;service=S-1-5-21-34256453-3348971241-2809240126-1648;scope=S-1-5-21-34256453-3348971241-2809240126-1647'
function Read-AuthWireInventoryGpoState {
 $g=Get-GPO -Guid $awGpo -Domain $awDomain -Server $awServer -ErrorAction Stop
 if($g.Id -ne $awGpo -or $g.DisplayName -cne 'AuthWire-Managed-Deployment-4c23eebe' -or $g.Description -cne $awMarker -or $g.GpoStatus.ToString() -cne 'AllSettingsEnabled'){throw 'OWNED_GPO_MISMATCH'}
 $raw=Get-GPOReport -Guid $awGpo -Domain $awDomain -Server $awServer -ReportType Xml -ErrorAction Stop
 if($raw.Length -gt 1048576 -or $raw -match '<!DOCTYPE'){throw 'GPO_REPORT_REJECTED'}
 $x=New-Object Xml.XmlDocument;$x.XmlResolver=$null;$x.LoadXml($raw)
 if($x.SelectNodes("/*[local-name()='GPO']/*[local-name()='LinksTo']").Count -ne 0 -or $x.SelectNodes("/*[local-name()='GPO']/*[local-name()='Computer' or local-name()='User']/*[local-name()='ExtensionData']").Count -ne 0){throw 'GPO_MUST_BE_EMPTY_UNLINKED'}
 foreach($kind in @('Computer','User')){foreach($name in @('VersionDirectory','VersionSysvol')){
  $node=$x.SelectSingleNode("/*[local-name()='GPO']/*[local-name()='$kind']/*[local-name()='$name']")
  if($null -eq $node -or $node.InnerText -cne '0'){throw 'GPO_VERSION_CHANGED'}
 }}
 return $g
}
$awBefore=Read-AuthWireInventoryGpoState
$awRoot='\\dc01.vizyonveri.local\SYSVOL\vizyonveri.local\Policies\{8c6808fd-a382-4bf2-9c9c-d9e1d46082a3}'
$awOne=Get-AuthWireSysvolInventory $awRoot
$awTwo=Get-AuthWireSysvolInventory $awRoot
$awAfter=Read-AuthWireInventoryGpoState
if($awBefore.ModificationTime -ne $awAfter.ModificationTime -or $awOne.Sha256 -cne $awTwo.Sha256){throw 'SYSVOL_OR_GPO_CHANGED_DURING_READ'}
$awEmpty=Test-AuthWireSysvolEmptyDeployment $awTwo
[ordered]@{
 Event='WINDOWS_SYSVOL_FULL_INVENTORY_READONLY';Version=1;Computer=$env:COMPUTERNAME
 GpoId=$awGpo.ToString('D');CheckedUtc=[DateTimeOffset]::UtcNow.ToString('o')
 InspectedAs=[Security.Principal.WindowsIdentity]::GetCurrent().Name
 InventoryStable=$true;EmptyDeploymentTree=$awEmpty;EntryCount=$awTwo.Entries.Count
 FileBytes=$awTwo.FileBytes;InventorySha256=$awTwo.Sha256;Entries=$awTwo.Entries
 Blockers=@(if(-not $awEmpty){'EXISTING_DESCENDANT_CONTENT_REQUIRES_REVIEW'})
 GmsaRuntimeTested=$false;EffectiveWriteAccessTested=$false;PackageStaged=$false
 AdChanged=$false;GpoChanged=$false;ServicesChanged=$false;KeyAclChanged=$false
 TrustStoreChanged=$false;ArtifactExecuted=$false;CanApplyGpo=$false
}|ConvertTo-Json -Depth 7
